#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAXN 100005

int main() {
    int N, M, s, t;
    scanf("%d %d %d %d", &N, &M, &s, &t);

    int d[MAXN];
    for (int i = 1; i <= N; i++) {
        scanf("%d", &d[i]);
    }

    // adjacency list for reverse edges (from lower to higher for DP)
    int *adj[MAXN];
    int deg[MAXN] = {0};
    int cap[MAXN];
    for (int i = 1; i <= N; i++) {
        cap[i] = 2; // at least one edge to lower dimension, plus maybe magic
        adj[i] = (int*)malloc(cap[i] * sizeof(int));
    }

    // add natural edges: i -> j for all j < i
    for (int i = 1; i <= N; i++) {
        for (int j = 1; j < i; j++) {
            if (deg[i] >= cap[i]) {
                cap[i] *= 2;
                adj[i] = (int*)realloc(adj[i], cap[i] * sizeof(int));
            }
            adj[i][deg[i]++] = j;
        }
    }

    // add magic edges
    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        if (deg[a] >= cap[a]) {
            cap[a] *= 2;
            adj[a] = (int*)realloc(adj[a], cap[a] * sizeof(int));
        }
        adj[a][deg[a]++] = b;
    }

    // DP from N down to 1
    long long dp[MAXN];
    dp[t] = 0;

    for (int i = N; i >= 1; i--) {
        if (i == t) continue;
        long long best = LLONG_MAX;
        for (int j = 0; j < deg[i]; j++) {
            int v = adj[i][j];
            if (v < i) { // only valid moves go to lower dimension
                if (dp[v] < best) best = dp[v];
            }
        }
        dp[i] = d[i] + best;
    }

    // Since curse at s is ignored, answer is dp[s] - d[s]
    printf("%lld\n", dp[s] - d[s]);

    // free memory
    for (int i = 1; i <= N; i++) free(adj[i]);

    return 0;
}

