#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int to, next;
} Edge;

typedef struct {
    ll val;
    int idx;
} Node;

static void swap(Node *a, Node *b) {
    Node t = *a;
    *a = *b;
    *b = t;
}

int main(void) {
    int N, M, s, t;
    if (scanf("%d %d %d %d", &N, &M, &s, &t) != 4) return 0;

    int *d = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) scanf("%d", &d[i]);

    int *head = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    Edge *edges = (Edge *)malloc(M * sizeof(Edge));
    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        edges[i].to = b;
        edges[i].next = head[a];
        head[a] = i;
    }

    const ll INF = (1LL << 60);

    ll *dist = (ll *)malloc((N + 1) * sizeof(ll));
    int *visited = (int *)calloc(N + 1, sizeof(int));
    for (int i = 1; i <= N; i++) dist[i] = INF;
    dist[s] = 0;

    Node *heap = (Node *)malloc((N + M + 5) * sizeof(Node));
    int hsz = 0;
    heap[++hsz] = (Node){0, s};

    int p = N + 1;  // smallest not-yet-added dimension for downward edges is p..current-1
    ll bestDown = INF;

    while (hsz > 0) {
        Node top = heap[1];
        heap[1] = heap[hsz--];

        int cur = 1;
        while (1) {
            int l = cur << 1, r = l + 1, smallest = cur;
            if (l <= hsz && heap[l].val < heap[smallest].val) smallest = l;
            if (r <= hsz && heap[r].val < heap[smallest].val) smallest = r;
            if (smallest == cur) break;
            swap(&heap[cur], &heap[smallest]);
            cur = smallest;
        }

        ll du = top.val;
        int u = top.idx;
        if (visited[u]) continue;
        visited[u] = 1;

        if (u == t) break;

        if (du + d[u] < bestDown) bestDown = du + d[u];

        while (p > u) {
            p--;
            if (!visited[p] && bestDown < INF) {
                ll nd = bestDown;
                if (nd < dist[p]) {
                    dist[p] = nd;
                    heap[++hsz] = (Node){nd, p};
                    int x = hsz;
                    while (x > 1 && heap[x].val < heap[x >> 1].val) {
                        swap(&heap[x], &heap[x >> 1]);
                        x >>= 1;
                    }
                }
            }
        }

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (visited[v]) continue;
            ll nd = du + d[v];
            if (nd < dist[v]) {
                dist[v] = nd;
                heap[++hsz] = (Node){nd, v};
                int x = hsz;
                while (x > 1 && heap[x].val < heap[x >> 1].val) {
                    swap(&heap[x], &heap[x >> 1]);
                    x >>= 1;
                }
            }
        }
    }

    printf("%lld\n", dist[t]);

    free(d);
    free(head);
    free(edges);
    free(dist);
    free(visited);
    free(heap);
    return 0;
}

