int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, s, t;
    cin >> N >> M >> s >> t;
    vector<int> d(N+1);
    for (int i = 1; i <= N; i++) cin >> d[i];

    vector<vector<int>> adj(N+1);
    for (int i = 0; i < M; i++) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
    }

    // Dijkstra on max dimension index
    const int INF = 1e9;
    vector<int> max_dim(N+1, INF);
    max_dim[s] = 0; // starting point, no curse counted
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
    pq.push({0, s});

    while (!pq.empty()) {
        auto [cur_max, u] = pq.top(); pq.pop();
        if (cur_max != max_dim[u]) continue;
        if (u == t) break;
        for (int v : adj[u]) {
            int new_max = max(cur_max, v);
            if (new_max < max_dim[v]) {
                max_dim[v] = new_max;
                pq.push({new_max, v});
            }
        }
    }

    cout << d[max_dim[t]] << "\n";
    return 0;
}

