#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, s, t;
    cin >> N >> M >> s >> t;

    vector<long long> d(N + 1), pref(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        cin >> d[i];
        pref[i] = pref[i - 1] + d[i];
    }

    vector<vector<int>> to(N + 1);
    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        to[a].push_back(b);
    }

    const long long INF = (1LL << 60);
    vector<long long> dp(N + 1, INF);

    // Cost to move from x to y (x > y) using free downward movement:
    // newly received curses are y, y+1, ..., x-1 => pref[x-1] - pref[y-1]
    // Cost to use magic x -> y:
    // newly received curses are all dimensions > x and <= y, i.e. x+1..y => pref[y] - pref[x]

    if (s > t) {
        dp[s] = 0;
        for (int i = s; i >= t; --i) {
            if (dp[i] == INF) continue;

            // Free moves downward
            // Relax all smaller dimensions implicitly later; do direct transition to t-range by DP recurrence
            // Since free move graph is complete downward, we can derive:
            // dp[j] = min over i>j (dp[i] + pref[i-1]-pref[j-1])
            // We'll handle this with a running minimum in descending order.
        }

        long long best = INF;
        for (int i = N; i >= 1; --i) {
            if (dp[i] != INF) {
                best = min(best, dp[i] + pref[i - 1]);
            }
            if (best != INF) {
                dp[i] = min(dp[i], best - pref[i - 1]);
            }
            for (int b : to[i]) {
                if (dp[i] == INF) continue;
                dp[b] = min(dp[b], dp[i] + (pref[b] - pref[i]));
            }
        }
        cout << dp[t] << '\n';
    } else {
        dp[s] = 0;
        long long best = INF;
        for (int i = N; i >= 1; --i) {
            if (dp[i] != INF) {
                best = min(best, dp[i] + pref[i - 1]);
            }
            if (best != INF) {
                dp[i] = min(dp[i], best - pref[i - 1]);
            }
            for (int b : to[i]) {
                if (dp[i] == INF) continue;
                dp[b] = min(dp[b], dp[i] + (pref[b] - pref[i]));
            }
        }
        cout << dp[t] << '\n';
    }

    return 0;
}

