        int[] d = new int[N + 1];
        st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= N; i++) d[i] = Integer.parseInt(st.nextToken());
        List<int[]>[] magicByA = new List[N + 1];
        for (int i = 1; i <= N; i++) magicByA[i] = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken()), b = Integer.parseInt(st.nextToken());
            if (b > a) magicByA[a].add(new int[]{b});
            // if b < a, it's going down which is free anyway
        }
        if (t <= s) { System.out.println(0); return; }
        long[] dist = new long[N + 1];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[s] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(x -> x[0]));
        pq.offer(new long[]{0, s});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long cost = cur[0]; int m = (int) cur[1];
            if (cost > dist[m]) continue;
            if (m >= t) { System.out.println(cost); return; }
            for (int a = 1; a <= m; a++) {
                for (int[] mg : magicByA[a]) {
                    int b = mg[0];
                    if (b > m) {
                        long nc = cost + d[b];
                        if (nc < dist[b]) { dist[b] = nc; pq.offer(new long[]{nc, b}); }
                    }
                }
            }
        }
        System.out.println(dist[t]);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int M = fs.nextInt();
        int s = fs.nextInt();
        int t = fs.nextInt();

        long[] d = new long[N + 1];
        for (int i = 1; i <= N; i++) d[i] = fs.nextInt();

        @SuppressWarnings("unchecked")
        ArrayList<Integer>[] from = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) from[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            from[a].add(b);
        }

        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[N + 1];
        Arrays.fill(dp, INF);

        // dp[x]: minimum additional damage needed to eventually reach t
        // when currently at dimension x and curse of x is already ignored/received.
        dp[t] = 0;

        // Maintain suffix minimum of dp[j] + d[j] for j > i,
        // representing moving freely downward from i to some j < i.
        long suffixMin = INF;

        for (int i = N; i >= 1; i--) {
            if (i < N) {
                suffixMin = Math.min(suffixMin, dp[i + 1] + d[i + 1]);
            }

            if (i != t) {
                long best = suffixMin; // free move to any lower dimension
                for (int b : from[i]) {
                    best = Math.min(best, dp[b] + d[b]); // magic move
                }
                dp[i] = best;
            }
        }

        System.out.println(dp[s]);
    }
}
